package com.bank.invsettle.service;

import java.util.logging.Logger;

// Subset Sum: boolean DP, reverse target loop so each invoice is used once.
public class InvoiceSettlementService {
    private static final Logger log = Logger.getLogger(InvoiceSettlementService.class.getName());

    public boolean canSettleExactly(int[] invoices, int amountDue) {
        boolean[] dp = new boolean[amountDue + 1];
        dp[0] = true;                                      // empty subset sums to 0
        for (int inv : invoices) {
            for (int s = amountDue; s >= inv; s--) {        // DOWNWARD → each invoice once
                if (dp[s - inv]) dp[s] = true;             // extend a reachable sum
            }
            if (dp[amountDue]) break;                      // early exit once matched
        }
        final boolean result = dp[amountDue];
        log.info(() -> "Can settle exactly " + amountDue + "? " + result);
        return dp[amountDue];
    }
}
