package com.bank.invsettle;

import com.bank.invsettle.service.InvoiceSettlementService;
import java.util.logging.Logger;

public class InvoiceSettlementApplication {
    private static final Logger log = Logger.getLogger(InvoiceSettlementApplication.class.getName());

    public static void main(String[] args) {
        InvoiceSettlementService service = new InvoiceSettlementService();
        int[] invoices = {3, 34, 4, 12, 5, 2};             // invoice amounts (scaled)
        boolean ok = service.canSettleExactly(invoices, 9); // amount due = 9
        log.info(() -> "Exact settlement possible = " + ok);
    }
}
